WITH remaining_keys AS (SELECT dept_name, id FROM departments INTERSECT SELECT dept_name, id FROM departments WHERE location = 'Chiang Mai'), verified AS (SELECT s.* FROM departments s JOIN remaining_keys k ON s.dept_name = k.dept_name AND s.id = k.id) SELECT CASE WHEN budget >= 3395000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, STDDEV_SAMP(budget) AS budget_stddev, COUNT_IF(location = 'Tokyo') AS tokyo_events, APPROX_PERCENTILE(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles, PERCENTILE_APPROX(budget, 0.95) AS budget_p95, PERCENTILE_APPROX(budget, 0.95) AS budget_p95_2, SIZE(COLLECT_SET(location)) AS num_locations FROM verified GROUP BY CASE WHEN budget >= 3395000 THEN 'HIGH' ELSE 'LOW' END ORDER BY budget_tier;
